# 在成绩列表中用二分查找判断某个分数是否存在。
# values 可能未按升序排列。


def contains(values, target):
    lo, hi = 0, len(values) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if values[mid] == target:
            return True
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

